#!/usr/bin/env node
/**
 * Tests for the guard failure policy: the deny checks all run (deny wins, asks merge into one ask), and a guard
 * that fails asks, never approves. Zero dependencies — `node:test` on Node 18+.
 *
 *   node --test tools/guard-shell-failsafe.test.mjs
 *
 * evaluate() is loaded with fake checks by patching the exports of the lib modules before lib/guard.js is
 * required; the process-level cases run copies of hooks/ with a broken module.
 *
 * Generated by Claude Code at the user's request.
 */

import { test, after } from 'node:test';
import assert from 'node:assert/strict';
import { createRequire } from 'node:module';
import { spawnSync } from 'node:child_process';
import { mkdtempSync, cpSync, readFileSync, writeFileSync, rmSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { tmpdir } from 'node:os';
import { fileURLToPath } from 'node:url';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const scratch = mkdtempSync(join(tmpdir(), 'failsafe-'));
process.env.HOME = scratch;
process.env.USERPROFILE = scratch;
after(() => { try { rmSync(scratch, { recursive: true, force: true }); } catch { /* tmp */ } });

const require = createRequire(import.meta.url);
const GUARD = require.resolve(join(ROOT, 'hooks', 'lib', 'guard.js'));

/** `evaluate` of a fresh lib/guard.js whose required modules export the patched functions. */
function loadEvaluate(patches) {
  const restore = [];
  for (const [file, patch] of Object.entries(patches)) {
    const mod = require(join(ROOT, 'hooks', 'lib', `${file}.js`));
    restore.push([mod, { ...mod }]);
    Object.assign(mod, patch);
  }
  delete require.cache[GUARD];
  const { evaluate } = require(GUARD);
  for (const [mod, original] of restore) Object.assign(mod, original);
  delete require.cache[GUARD];
  return evaluate;
}

const payload = { tool_name: 'Bash', tool_input: { command: 'echo hi' }, cwd: scratch };
const boom = () => { throw new Error('boom'); };

test('given sql-target returning an ask and secret-read returning a deny, when evaluate runs, then the result is deny', () => {
  // Given
  const evaluate = loadEvaluate({ 'sql-target': { checkSqlTarget: () => ({ decision: 'ask', reason: 'SQL-ASK' }) }, 'secret-read': { checkSecretRead: () => ({ reason: 'SECRET-DENY' }) } });

  // When
  const result = evaluate(payload);

  // Then
  assert.equal(result.decision, 'deny');
  assert.match(result.reason, /SECRET-DENY/);
});

test('given two deny checks each returning an ask, when evaluate runs, then one ask results whose reason names both', () => {
  // Given
  const evaluate = loadEvaluate({ 'sql-target': { checkSqlTarget: () => ({ decision: 'ask', reason: 'SQL-ASK' }) }, 'secret-read': { checkSecretRead: () => ({ decision: 'ask', reason: 'SECRET-ASK' }) } });

  // When
  const result = evaluate(payload);

  // Then
  assert.equal(result.decision, 'ask');
  assert.match(result.reason, /SQL-ASK/);
  assert.match(result.reason, /SECRET-ASK/);
});

test('given a deny check returning {decision: ask}, when evaluate runs, then the result is ask, never deny', () => {
  // Given
  const evaluate = loadEvaluate({ 'sql-target': { checkSqlTarget: () => ({ decision: 'ask', reason: 'SQL-ASK' }) } });

  // When
  const result = evaluate(payload);

  // Then
  assert.equal(result.decision, 'ask');
});

test('given a deny check that throws, when evaluate runs, then the result is ask naming the failed check', () => {
  // Given
  const cases = [
    ['sql-target', { 'sql-target': { checkSqlTarget: boom } }],
    ['secret-read', { 'secret-read': { checkSecretRead: boom } }],
    ['read-only-agent', { 'read-only-agents': { READ_ONLY_AGENTS: { has: boom } } }],
    ['browser-use-cli', { 'browser-use-cli': { checkBrowserUseCli: boom } }],
  ];

  for (const [name, patches] of cases) {
    // When
    const result = loadEvaluate(patches)({ ...payload, agent_type: 'code-reviewer' });

    // Then
    assert.equal(result?.decision, 'ask', name);
    assert.match(result.reason, new RegExp(name), name);
  }
});

test('given a rewrite check that throws, when evaluate runs, then the call still proceeds', () => {
  // Given
  const cases = [{ 'az-pin': { planAzPin: boom } }, { 'output-filter': { planFilter: boom } }];

  for (const patches of cases) {
    // When
    const result = loadEvaluate(patches)(payload);

    // Then
    assert.equal(result, null);
  }
});

function spawnHook(hooksDir, file, input, env = {}) {
  return spawnSync(process.execPath, [join(hooksDir, file)], { input, encoding: 'utf8', env: { ...process.env, ...env } });
}
const decisionOf = (r) => JSON.parse(r.stdout).hookSpecificOutput;
const shellInput = JSON.stringify(payload);

test('given a copy of hooks whose lib/guard.js and lib/decision.js throw at require time, when guard-shell.js runs, then stdout is a PreToolUse ask built without lib/decision', () => {
  // Given
  const hooks = join(scratch, 'hooks-broken');
  cpSync(join(ROOT, 'hooks'), hooks, { recursive: true });
  writeFileSync(join(hooks, 'lib', 'guard.js'), "throw new Error('broken guard');\n");
  writeFileSync(join(hooks, 'lib', 'decision.js'), "throw new Error('broken decision');\n");

  // When
  const r = spawnHook(hooks, 'guard-shell.js', shellInput);

  // Then
  assert.equal(r.status, 0);
  const out = decisionOf(r);
  assert.equal(out.hookEventName, 'PreToolUse');
  assert.equal(out.permissionDecision, 'ask');
});

test('given unreadable stdin, when guard-shell.js and secret-scan.js run, then each asks, never approves', () => {
  // Given
  const hooks = join(ROOT, 'hooks');

  for (const file of ['guard-shell.js', 'secret-scan.js']) {
    // When
    const r = spawnHook(hooks, file, 'this is not json');

    // Then
    assert.equal(r.status, 0, file);
    assert.equal(decisionOf(r).permissionDecision, 'ask', file);
  }
});

test('given the settings.json inline hook command of guard-shell and secret-scan with CLAUDE_HOOKS at a missing dir, when it runs, then it prints the raw ask JSON, not exit 2', () => {
  // Given
  const settings = JSON.parse(readFileSync(join(ROOT, 'settings.json'), 'utf8'));
  const inline = Object.values(settings.hooks).flat().flatMap((group) => group.hooks ?? [])
    .filter((hook) => hook.command === 'node' && /guard-shell\.js|secret-scan\.js/.test(hook.args?.[1] ?? ''));

  // When / Then
  assert.equal(inline.length, 2);
  for (const hook of inline) {
    const r = spawnSync(process.execPath, hook.args, { input: shellInput, encoding: 'utf8', env: { ...process.env, CLAUDE_HOOKS: join(scratch, 'no-such-dir') } });
    assert.equal(r.status, 0, hook.args[1]);
    assert.equal(decisionOf(r).permissionDecision, 'ask', hook.args[1]);
  }
});

test('given the guard-shell.js header comment, when read, then it no longer says errors let the command through', () => {
  // Given
  const source = readFileSync(join(ROOT, 'hooks', 'guard-shell.js'), 'utf8');

  // When
  const header = source.slice(0, source.indexOf("'use strict'"));

  // Then
  assert.doesNotMatch(header, /any error lets the command through/i);
});
